// HEC IELTS Speaking & Listening, Year 1, Term 4 (Science, cities, the planet): class plays for
// Sun Class (grades 8-10). Original scripts by the school; no test material, no promise of a band.
import type { Play, PlayLine } from "@/lib/lessonDecks/plays";

const r = (role: string, text: string, d?: string): PlayLine => (d ? { role, text, do: d } : { role, text });
// A group line pinned to one member: the child who pulls the cup, holds the last card, rings the bell.
const pin = (role: string, member: number, text: string, d?: string): PlayLine => ({ role, text, member, ...(d ? { do: d } : {}) });
const all = (role: string, text: string, d?: string): PlayLine => ({ role, text, all: true, ...(d ? { do: d } : {}) });
const st = (stage: string, cond?: string): PlayLine => (cond ? { stage, if: cond } : { stage });
const ev = (everyone: string, d?: string): PlayLine => (d ? { everyone, do: d } : { everyone });
// Script, then key words, then no script at all: the last round is always the students' own words.
const rh = (cards: string, noScript: string) => [
  { round: "Read-through with scripts", minutes: 9, how: "Two minutes to hand out the parts and the props. Then read the play aloud with parts, standing where the stage directions say. Hidden things stay hidden: nobody looks inside another character's sack, card, chart, notebook or phone before the script says so. Then the teacher's one-minute fix." },
  { round: "Key-word cards", minutes: 10, how: `Scripts down. Each part keeps a card with key words only, and the scene runs faster, in the 4/3/2 spirit: the same story in less time. ${cards} Then a second one-minute fix.` },
  { round: "No script, improvised ending", minutes: 14, how: `Every paper away. Play the story from memory in your own words, keeping the frames (about eight minutes; Scene 3 alone if time is short), then play the improvised scene (about five minutes). ${noScript}` },
];
const mk = (n: number, p: Omit<Play, "id" | "course" | "level" | "unit" | "band">): Play => ({
  id: `hec-ielts-y1-t4-p${n}`, course: "hec-ielts-sl", level: 1, unit: 4, band: "13-16", ...p,
});

